import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import ControlPanel from './ControlPanel';
import {
  VisualizationContainer,
  StatusMessage,
  ResultsContainer,
  ResultItem
} from './VisualizationStyles';

// Debug log
console.log('AddTwoNumbersVisualization component is being loaded');

const ControlContainer = styled.div`
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
`;

const Button = styled.button`
  padding: 0.5rem 1rem;
  background: var(--primary);
  color: white;
  border: none;
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: all 0.3s ease;
  
  &:hover {
    background: var(--primary-dark);
  }
  
  &:disabled {
    background: #cccccc;
    cursor: not-allowed;
  }
`;

const LinkedListsContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
  margin-bottom: 2rem;
`;

const LinkedList = styled.div`
  display: flex;
  align-items: center;
  position: relative;
  margin-bottom: 1rem;
`;

const ListLabel = styled.div`
  position: absolute;
  left: -40px;
  font-weight: 500;
  color: var(--text-primary);
`;

const LinkedListNode = styled.div`
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid ${props => {
    if (props.isActive) return 'var(--primary)';
    if (props.isResult) return '#4caf50';
    return '#e0e0e0';
  }};
  background-color: ${props => {
    if (props.isActive) return 'rgba(98, 0, 238, 0.1)';
    if (props.isResult) return 'rgba(76, 175, 80, 0.1)';
    return 'white';
  }};
  margin: 0 2px;
  border-radius: 50%;
  position: relative;
  font-weight: ${props => props.isActive || props.isResult ? 'bold' : 'normal'};
`;

const Arrow = styled.div`
  width: 20px;
  height: 2px;
  background-color: #e0e0e0;
  position: relative;
  
  &::after {
    content: '';
    position: absolute;
    right: 0;
    top: -3px;
    width: 0;
    height: 0;
    border-top: 4px solid transparent;
    border-bottom: 4px solid transparent;
    border-left: 7px solid #e0e0e0;
  }
`;

const CalculationBox = styled.div`
  display: flex;
  align-items: center;
  gap: 0.5rem;
  justify-content: center;
  margin: 1rem 0;
  padding: 0.75rem;
  border: 1px dashed #e0e0e0;
  border-radius: var(--border-radius);
`;

const ExampleSection = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1rem;
`;

const ExampleButton = styled.button`
  padding: 0.5rem 1rem;
  background: ${props => props.isSelected ? 'var(--primary)' : '#f5f5f5'};
  color: ${props => props.isSelected ? 'white' : 'var(--text-primary)'};
  border: 1px solid ${props => props.isSelected ? 'var(--primary)' : '#e0e0e0'};
  border-radius: var(--border-radius);
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 0.9rem;
  
  &:hover {
    background: ${props => props.isSelected ? 'var(--primary-dark)' : '#e0e0e0'};
  }
`;

const InputContainer = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
`;

const InputField = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const InputLabel = styled.label`
  margin-bottom: 0.5rem;
  font-weight: 500;
`;

const Input = styled.input`
  padding: 0.5rem;
  border: 1px solid #e0e0e0;
  border-radius: var(--border-radius);
  width: 200px;
  text-align: center;
  font-family: monospace;
`;

const HelpText = styled.div`
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-top: 0.25rem;
  text-align: center;
`;

const DEFAULT_LIST1 = [2, 4, 3]; // 342
const DEFAULT_LIST2 = [5, 6, 4]; // 465
// Sum should be 807 represented as [7, 0, 8]

const EXAMPLES = [
  { label: "Example 1", list1: [2, 4, 3], list2: [5, 6, 4], number1: 342, number2: 465 },
  { label: "Example 2", list1: [0], list2: [0], number1: 0, number2: 0 },
  { label: "Example 3", list1: [9, 9, 9, 9, 9, 9, 9], list2: [9, 9, 9, 9], number1: 9999999, number2: 9999 },
  { label: "Example 4", list1: [9], list2: [1, 9, 9, 9, 9, 9, 9, 9, 9, 9], number1: 9, number2: 9999999991 }
];

const AddTwoNumbersVisualization = () => {
  const [list1, setList1] = useState(DEFAULT_LIST1);
  const [list2, setList2] = useState(DEFAULT_LIST2);
  const [result, setResult] = useState([]);
  const [currentStep, setCurrentStep] = useState(0);
  const [activeNode1, setActiveNode1] = useState(null);
  const [activeNode2, setActiveNode2] = useState(null);
  const [carry, setCarry] = useState(0);
  const [sum, setSum] = useState(null);
  const [message, setMessage] = useState({ text: 'Click "Start" to begin the visualization.', type: 'info' });
  const [isRunning, setIsRunning] = useState(false);
  const [speed, setSpeed] = useState(1000); // in milliseconds
  const [isComplete, setIsComplete] = useState(false);
  const [list1Input, setList1Input] = useState(DEFAULT_LIST1.join(','));
  const [list2Input, setList2Input] = useState(DEFAULT_LIST2.join(','));
  const [originalNumber1, setOriginalNumber1] = useState(342);
  const [originalNumber2, setOriginalNumber2] = useState(465);
  const [selectedExample, setSelectedExample] = useState(0);
  
  const maxLength = Math.max(list1.length, list2.length);
  const totalSteps = maxLength + (carry > 0 ? 1 : 0);
  
  // Parse the input strings into arrays and calculate original numbers
  const handleList1Change = (e) => {
    setList1Input(e.target.value);
    try {
      const newList = e.target.value.split(',').map(item => parseInt(item.trim())).filter(num => !isNaN(num));
      setList1(newList);
      const originalNum = calculateOriginalNumber(newList);
      setOriginalNumber1(originalNum);
      setSelectedExample(-1); // Deselect any example
      reset();
    } catch (error) {
      console.error("Invalid input format for list 1");
    }
  };

  const handleList2Change = (e) => {
    setList2Input(e.target.value);
    try {
      const newList = e.target.value.split(',').map(item => parseInt(item.trim())).filter(num => !isNaN(num));
      setList2(newList);
      const originalNum = calculateOriginalNumber(newList);
      setOriginalNumber2(originalNum);
      setSelectedExample(-1); // Deselect any example
      reset();
    } catch (error) {
      console.error("Invalid input format for list 2");
    }
  };

  const selectExample = (index) => {
    setSelectedExample(index);
    const example = EXAMPLES[index];
    setList1(example.list1);
    setList2(example.list2);
    setList1Input(example.list1.join(','));
    setList2Input(example.list2.join(','));
    setOriginalNumber1(example.number1);
    setOriginalNumber2(example.number2);
    reset();
  };

  // Calculate original number from reversed digits
  const calculateOriginalNumber = (list) => {
    let num = 0;
    for (let i = list.length - 1; i >= 0; i--) {
      num = num * 10 + list[i];
    }
    return num;
  };
  
  const reset = () => {
    setCurrentStep(0);
    setActiveNode1(null);
    setActiveNode2(null);
    setCarry(0);
    setSum(null);
    setResult([]);
    setMessage({ text: 'Click "Start" to begin the visualization.', type: 'info' });
    setIsRunning(false);
    setIsComplete(false);
  };
  
  const start = () => {
    reset();
    setIsRunning(true);
  };
  
  const nextStep = () => {
    if (currentStep < totalSteps) {
      setCurrentStep(prev => prev + 1);
    } else {
      setIsRunning(false);
      setIsComplete(true);
    }
  };
  
  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(prev => prev - 1);
    }
  };
  
  useEffect(() => {
    if (!isRunning) return;
    
    if (currentStep >= list1.length && currentStep >= list2.length && carry === 0) {
      setMessage({ 
        text: 'Addition complete! Result: ' + result.join(' → '), 
        type: 'success' 
      });
      setIsRunning(false);
      setIsComplete(true);
      return;
    }
    
    const position = currentStep;
    
    // Get values at current position or 0 if out of bounds
    const val1 = position < list1.length ? list1[position] : 0;
    const val2 = position < list2.length ? list2[position] : 0;
    
    // Set active nodes
    setActiveNode1(position < list1.length ? position : null);
    setActiveNode2(position < list2.length ? position : null);
    
    // Calculate sum and new carry
    const currentSum = val1 + val2 + carry;
    const newCarry = Math.floor(currentSum / 10);
    const digit = currentSum % 10;
    
    setSum({ val1, val2, carry, currentSum, digit });
    
    setMessage({ 
      text: `Adding ${val1} + ${val2} + ${carry} (carry) = ${currentSum}, digit: ${digit}, new carry: ${newCarry}`, 
      type: 'info' 
    });
    
    // Add result after a delay to show the calculation first
    const timer = setTimeout(() => {
      setResult(prev => [...prev, digit]);
      setCarry(newCarry);
      
      // Move to next position
      const nextTimer = setTimeout(() => {
        setCurrentStep(prev => prev + 1);
      }, speed / 2);
      
      return () => clearTimeout(nextTimer);
    }, speed);
    
    return () => clearTimeout(timer);
  }, [currentStep, isRunning, list1, list2, carry, speed, result]);
  
  return (
    <VisualizationContainer>
      <ControlPanel
        onStart={start}
        onNext={nextStep}
        onPrev={prevStep}
        onReset={reset}
        isRunning={isRunning}
        canGoNext={currentStep < totalSteps && !isComplete}
        canGoPrev={currentStep > 0}
        speed={speed}
        onSpeedChange={setSpeed}
        showPrev={true}
      />
      
      <ExampleSection>
        <div style={{ marginRight: '0.5rem' }}>Examples:</div>
        {EXAMPLES.map((example, index) => (
          <ExampleButton
            key={index}
            isSelected={selectedExample === index}
            onClick={() => selectExample(index)}
            disabled={isRunning}
          >
            {example.label}
          </ExampleButton>
        ))}
      </ExampleSection>
      
      <InputContainer>
        <InputField>
          <InputLabel>First List (reversed digits):</InputLabel>
          <Input 
            value={list1Input}
            onChange={handleList1Change}
            disabled={isRunning}
            placeholder="2,4,3"
          />
          <HelpText>Number: {originalNumber1}</HelpText>
        </InputField>
        
        <InputField>
          <InputLabel>Second List (reversed digits):</InputLabel>
          <Input 
            value={list2Input}
            onChange={handleList2Change}
            disabled={isRunning}
            placeholder="5,6,4"
          />
          <HelpText>Number: {originalNumber2}</HelpText>
        </InputField>
      </InputContainer>
      
      <LinkedListsContainer>
        <LinkedList>
          <ListLabel>l1:</ListLabel>
          {list1.map((value, index) => (
            <React.Fragment key={index}>
              <LinkedListNode isActive={index === activeNode1}>
                {value}
              </LinkedListNode>
              {index < list1.length - 1 && <Arrow />}
            </React.Fragment>
          ))}
        </LinkedList>
        
        <LinkedList>
          <ListLabel>l2:</ListLabel>
          {list2.map((value, index) => (
            <React.Fragment key={index}>
              <LinkedListNode isActive={index === activeNode2}>
                {value}
              </LinkedListNode>
              {index < list2.length - 1 && <Arrow />}
            </React.Fragment>
          ))}
        </LinkedList>
        
        {result.length > 0 && (
          <LinkedList>
            <ListLabel>sum:</ListLabel>
            {result.map((value, index) => (
              <React.Fragment key={index}>
                <LinkedListNode isResult>
                  {value}
                </LinkedListNode>
                {index < result.length - 1 && <Arrow />}
              </React.Fragment>
            ))}
          </LinkedList>
        )}
      </LinkedListsContainer>
      
      {sum && (
        <CalculationBox>
          <div>
            <strong>Current:</strong> {sum.val1} + {sum.val2} + {sum.carry} (carry) = {sum.currentSum}
          </div>
          <div>
            <strong>Digit:</strong> {sum.digit}
          </div>
          <div>
            <strong>New Carry:</strong> {Math.floor(sum.currentSum / 10)}
          </div>
        </CalculationBox>
      )}
      
      <StatusMessage type={message.type}>
        {message.text}
      </StatusMessage>
      
      {isComplete && (
        <ResultsContainer>
          <ResultItem>
            <strong>Input Numbers:</strong> {originalNumber1} + {originalNumber2} = {originalNumber1 + originalNumber2}
          </ResultItem>
          <ResultItem>
            <strong>Linked List Result:</strong> [{result.join(', ')}]
          </ResultItem>
        </ResultsContainer>
      )}
    </VisualizationContainer>
  );
};

export default AddTwoNumbersVisualization; 